input.new_string:
if width < 1:
    raise ValueError("width must be at least 1")

words = []
for word in text.split():
    if len(word) <= width:
        words.append(word)
    else:
        for start in range(0, len(word), width):
            words.append(word[start : start + width])

if not words:
    return []

lines = []
current = ""
for word in words:
    if not current:
        current = word
    elif len(current) + 1 + len(word) <= width:
        current += " " + word
    else:
        lines.append(current)
        current = word
lines.append(current)
return lines
